class Solution:
    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums)
        total_sum = sum(nums)
        left_sum = sum(nums[:n//2])
        count = 0

        if left_sum > total_sum - left_sum:
            count += 1

        for i in range(1, n):
            left_sum = left_sum - nums[i - 1] + nums[(i - 1 + n // 2) % n]
            if left_sum > total_sum - left_sum:
                count += 1

        return count

